static QJsonArray parseOEM(const QByteArray&data){QJsonArray rows;const auto base=QDateTime::fromString("2012-06-10T00:00:00Z",Qt::ISODate);for(auto line:QString::fromUtf8(data).split('\n')){line=line.trimmed();auto m=QRegularExpression("^(\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d)(\\.\\d+)?\\s+(.*)$").match(line);if(!m.hasMatch())continue;auto date=QDateTime::fromString(m.captured(1)+"Z",Qt::ISODate);require(date.isValid(),"Batch OEM date invalid");QJsonArray row{base.msecsTo(date)/1000.+m.captured(2).toDouble()};auto fields=m.captured(3).split(QRegularExpression("\\s+"),Qt::SkipEmptyParts);require(fields.size()==6,"Batch OEM width differs");for(auto f:fields){bool ok=false;double v=f.toDouble(&ok);require(ok&&std::isfinite(v),"Batch OEM nonfinite");row.append(v);}rows.append(row);}return rows;}
static std::array<double,6> advance(std::array<double,6>s,double dt){auto rhs=[](const std::array<double,6>&x){double r=std::sqrt(x[0]*x[0]+x[1]*x[1]+x[2]*x[2]);return std::array<double,6>{x[3],x[4],x[5],-mu*x[0]/(r*r*r),-mu*x[1]/(r*r*r),-mu*x[2]/(r*r*r)};};int n=std::max(1,int(std::ceil(std::abs(dt)/.2)));double h=dt/n;for(int k=0;k<n;++k){auto a=rhs(s),b=s,c=s,d=s;for(int i=0;i<6;++i)b[i]+=h*a[i]/2;b=rhs(b);for(int i=0;i<6;++i)c[i]+=h*b[i]/2;c=rhs(c);for(int i=0;i<6;++i)d[i]+=h*c[i];d=rhs(d);for(int i=0;i<6;++i)s[i]+=h*(a[i]+2*b[i]+2*c[i]+d[i])/6;}return s;}
